events.content:
"""长程执行（run）的请求/响应与事件模型。

run 是「一次任务从提交到收尾」的完整生命周期，它建立在 P0 工具面之上：
sidecar 负责决定调哪个工具，工具执行仍然全部经 `call_tool` 落到会话场景与 trace。
本模块只描述编排层的数据形状，不含任何业务判定。

红线延续：事件与计划步骤里**不出现坐标**——计划是业务语言的步骤清单，
观测摘要取自工具出参的 `result_summary`，坐标只存在于最终 diff 的求解结果中。
"""
from __future__ import annotations

from typing import Any, Literal

from pydantic import BaseModel, Field

RunStatus = Literal[
    "planning",      # 已提交任务，sidecar 正在产出计划
    "awaiting_plan", # 计划已就绪，等用户批准
    "running",       # 已批准，执行循环进行中
    "finished",      # 正常结束（含"达上限后收尾"）
    "failed",        # 异常结束（网关不可用、sidecar 不可达等）
    "aborted",       # 用户中止
]

RunEventType = Literal[
    "plan_ready", "step_started", "tool_called", "step_finished",
    "validation_result", "run_finished", "run_failed",
]


class PlanStep(BaseModel):
    """计划中的一步，业务语言描述，无坐标。

    `index` 是稳定序号，用户勾选排除某步时按它回传；sidecar 收到的是
    过滤后的清单，被排除的步骤不会进入执行提示词。
    """

    index: int = Field(ge=0)
    title: str
    detail: str = ""


class RunCreate(BaseModel):
    session_id: str
    task: str = Field(min_length=1, max_length=2000)


class RunApprove(BaseModel):
    """计划批准：excluded_steps 为用户勾掉的步骤序号。

    全部勾掉等于放弃本次任务，视为拒绝（由 service 判定并终止 run）。
    """

    excluded_steps: list[int] = []


class RunEvent(BaseModel):
    """一条 SSE 事件。seq 在单个 run 内自增，供前端判断是否漏收。"""

    seq: int
    type: RunEventType
    timestamp: float
    payload: dict[str, Any] = {}


class RunRead(BaseModel):
    id: str
    session_id: str
    task: str
    status: RunStatus
    plan: list[PlanStep] = []
    steps_used: int = 0
    max_steps: int
    stop_reason: str = ""
    message: str = ""


class RunDiffRead(BaseModel):
    """run 结束后拉取的变更，转成前端既有 LayoutAssistResult 形状。

    字段名与 `LayoutAssistResponse` 对齐（reply/actions/earthworks/validation），
    前端因此可以把它直接赋给 `pendingProposal`，复用同一条幽灵预览通道，
    不需要为智能体另写一套预览与应用逻辑。
    """

    reply: str
    actions: list[Any] = []
    earthworks: list[Any] = []
    crane_actions: list[Any] = []
    validation: Any
    notes: list[str] = []
