"""智能体会话、工具面与长程执行接口（harness 无关的 HTTP 契约）。"""
from __future__ import annotations

import json

from fastapi import APIRouter
from fastapi.responses import StreamingResponse

from app.schemas.agent import (
    AgentSessionCreate,
    AgentSessionDeleted,
    AgentSessionRead,
    ToolCallRequest,
    ToolCallResponse,
    TraceRead,
)
from app.schemas.agent_run import RunApprove, RunCreate, RunDiffRead, RunRead
from app.services.agent import run_service
from app.services.agent import session as session_store
from app.services.agent import tools as tool_registry
from app.services.agent.session import SESSION_TTL_SECONDS

router = APIRouter()


def _session_read(state) -> AgentSessionRead:
    return AgentSessionRead(
        id=state.id,
        created_at=state.created_at,
        last_active_at=state.last_active_at,
        ttl_seconds=SESSION_TTL_SECONDS,
        object_count=len(state.scene.objects),
        checkpoint_count=len(state.checkpoints),
    )


@router.post("/api/agent/sessions", response_model=AgentSessionRead)
def create_session(request: AgentSessionCreate) -> AgentSessionRead:
    """建会话：上传完整场景快照，智能体后续在服务端副本上迭代。"""
    state = session_store.create_session(request.scene, request.milestones)
    return _session_read(state)


@router.delete("/api/agent/sessions/{session_id}", response_model=AgentSessionDeleted)
def delete_session(session_id: str) -> AgentSessionDeleted:
    deleted = session_store.delete_session(session_id)
    return AgentSessionDeleted(id=session_id, deleted=deleted)


@router.post("/api/agent/sessions/{session_id}/tools/{tool_name}", response_model=ToolCallResponse)
def call_tool(session_id: str, tool_name: str, request: ToolCallRequest) -> ToolCallResponse:
    """统一工具调用入口：未知工具名与非法入参由全局异常处理器统一转 HTTP 响应。"""
    state = session_store.get_session(session_id)
    result, trace_entry = tool_registry.call_tool(state, tool_name, request.params)
    return ToolCallResponse(
        tool=tool_name,
        seq=trace_entry.seq,
        duration_ms=trace_entry.duration_ms,
        result=result.model_dump(),
    )


@router.get("/api/agent/sessions/{session_id}/trace", response_model=TraceRead)
def get_trace(session_id: str) -> TraceRead:
    state = session_store.get_session(session_id)
    return TraceRead(session_id=session_id, entries=state.trace)


# --------------------------------------------------------------------------
# 长程执行（run）
# --------------------------------------------------------------------------

@router.post("/api/agent/runs", response_model=RunRead)
def create_run(request: RunCreate) -> RunRead:
    """提交长程任务：后台产出计划后转入待批准状态，进度经 SSE 推送。"""
    state = run_service.start_run(request.session_id, request.task)
    return run_service.run_read(state)


@router.get("/api/agent/runs/{run_id}", response_model=RunRead)
def get_run(run_id: str) -> RunRead:
    return run_service.run_read(run_service.get_run(run_id))


@router.post("/api/agent/runs/{run_id}/approve", response_model=RunRead)
def approve_run(run_id: str, request: RunApprove) -> RunRead:
    """批准计划并开始执行；被勾掉的步骤不会进入执行提示词。"""
    return run_service.run_read(run_service.approve_run(run_id, request.excluded_steps))


@router.post("/api/agent/runs/{run_id}/reject", response_model=RunRead)
def reject_run(run_id: str) -> RunRead:
    return run_service.run_read(run_service.reject_run(run_id))


@router.post("/api/agent/runs/{run_id}/abort", response_model=RunRead)
def abort_run(run_id: str) -> RunRead:
    """中止运行。服务端会话副本上的改动不回滚，但前端场景从未被触碰，
    用户不点应用即等于零影响。"""
    return run_service.run_read(run_service.abort_run(run_id))


@router.get("/api/agent/runs/{run_id}/events")
def run_events(run_id: str) -> StreamingResponse:
    """SSE 进度流：订阅时先补齐已发生的事件，再推送增量。

    终止事件（run_finished / run_failed）推完即关闭流，前端据此收尾。
    """
    state = run_service.get_run(run_id)

    def event_stream():
        for event in run_service.iter_events(state):
            # None 是静默期心跳：发一行 SSE 注释维持连接，前端据此判断链路仍活着。
            yield ": keep-alive\n\n" if event is None else _run_sse(event)

    return StreamingResponse(
        event_stream(),
        media_type="text/event-stream",
        headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
    )


def _run_sse(event) -> str:
    return f"event: {event.type}\ndata: {json.dumps(event.model_dump(), ensure_ascii=False, default=str)}\n\n"


@router.get("/api/agent/runs/{run_id}/diff", response_model=RunDiffRead)
def get_run_diff(run_id: str) -> RunDiffRead:
    """run 的最终变更，形状与布置方案一致，供前端走同一条幽灵预览通道。"""
    return run_service.run_diff(run_id)

