=====config.ts=====
/**
 * provider 配置：环境变量与后端 core/config.py 同名（QA_API_URL/QA_API_KEY/QA_MODEL），
 * 禁止硬编码密钥。QA_API_URL 默认值与后端 config.py 保持一致（仅是网关地址，非凭据）。
 */
import type { Model } from "@mariozechner/pi-ai";

export const QA_API_URL = (process.env.QA_API_URL ?? "https://c4ai.ccccltd.cn/api/compatible/v1").replace(/\/+$/, "");
export const QA_API_KEY = process.env.QA_API_KEY;
export const QA_MODEL = process.env.QA_MODEL ?? "jiaorong-deepseek-v4-pro";

/** P1 工具面所在的后端地址；与 vite 代理目标一致。 */
export const BACKEND_URL = (process.env.AGENT_BACKEND_URL ?? "http://localhost:8000").replace(/\/+$/, "");

/**
 * 工具调用模式。
 *
 * - native：走网关原生 function-calling（OpenAI tools 协议），**当前唯一已实现的模式**；
 * - prompt：提示词式 JSON 工具调用兜底，**不实现**——2026-08-24 实测确认网关原生支持
 *   function-calling（finish_reason=tool_calls，见 README「网关能力验证」节），
 *   兜底无适用场景。换到不支持 tools 协议的网关时再按当时实测结论补。
 *
 * 置为 prompt 时 runAgent 会显式报错退出，不会静默回落到 native。
 */
export const TOOL_MODE = (process.env.AGENT_TOOL_MODE ?? "native") as "native" | "prompt";

/** agent 循环步数上限（一步 = 一次 LLM 调用 + 其工具执行）。 */
export const MAX_STEPS = Number(process.env.AGENT_MAX_STEPS ?? 15);

export function requireApiKey(): string {
  if (!QA_API_KEY) {
    // 轨道红线 3 的降级提示：离线路径由 LR-05.P6 的脚本模式提供，本 sidecar 不兜底。
    console.error("需配置 QA_API_KEY，离线请等待 P6 脚本模式。");
    process.exit(1);
  }
  return QA_API_KEY;
}

/**
 * 以 OpenAI 兼容 provider 接入 pi：网关是 DeepSeek 系模型的企业代理，属 pi-ai
 * URL 自动探测覆盖不到的自定义端点，故显式给出 compat（按 DeepSeek 系保守取值：
 * 不发 store/strict/reasoning_effort，max_tokens 用旧字段名，思维链走 deepseek
 * 格式的 reasoning_content）。function-calling 支持与否由 npm run verify-tools
 * 实测，结论见 README「网关能力验证」节。
 */
export function buildModel(): Model<"openai-completions"> {
  return {
    id: QA_MODEL,
    name: `${QA_MODEL} (QA gateway)`,
    api: "openai-completions",
    provider: "qa-gateway",
    baseUrl: QA_API_URL,
    reasoning: true,
    input: ["text"],
    cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
    contextWindow: 128000,
    maxTokens: 8192,
    compat: {
      supportsStore: false,
      supportsStrictMode: false,
      supportsReasoningEffort: false,
      supportsDeveloperRole: false,
      maxTokensField: "max_tokens",
      thinkingFormat: "deepseek",
    },
  };
}

/**
 * agent 主循环：把 buildModel() 的 provider、prompts/system.md 的系统提示词、
 * buildTools() 的工具集装配成一次长程运行。
 *
 * 为什么用低层 runAgentLoop 而不是 Agent 类：步数上限要靠 AgentLoopConfig 的
 * shouldStopAfterTurn 实现（每个 turn 结束后判定是否还继续下一次 LLM 调用），
 * 而 Agent 类的 AgentOptions 不透出这个钩子（见 node_modules/@mariozechner/
 * pi-agent-core/dist/agent.d.ts 的 AgentOptions）。用 Agent 类只能靠 abort()
 * 硬打断，会把正常的「到达上限」染成 aborted，与 system.md 的终止条件对不上。
 *
 * 终止条件与 prompts/system.md 一致：
 * - 模型不再发起工具调用（自认完成或判定不可完成）→ 循环自然结束；
 * - 步数达 MAX_STEPS → shouldStopAfterTurn 收尾，属正常终止路径；
 * - 模型/网关报错 → 内核以 stopReason=error 结束，原样上报不掩盖。
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import type { AgentContext, AgentEvent, AgentMessage } from "@mariozechner/pi-agent-core";
import { runAgentLoop } from "@mariozechner/pi-agent-core";
import type { Message, Model } from "@mariozechner/pi-ai";
import { MAX_STEPS, QA_MODEL, TOOL_MODE, buildModel } from "./config.js";
import type { SessionRecorder } from "./sessionLog.js";
import { type ToolCallLog, buildTools } from "./toolBridge.js";

const PACKAGE_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));

export function loadSystemPrompt(): string {
  return readFileSync(join(PACKAGE_ROOT, "prompts", "system.md"), "utf8");
}

export type RunStopReason =
  | "completed"      // 模型不再调用工具，自认收尾
  | "max_steps"      // 步数上限
  | "model_error"    // 网关/模型报错
  | "aborted";

export interface RunResult {
  steps: number;
  stopReason: RunStopReason;
  errorMessage?: string;
  toolCalls: ToolCallLog[];
  /** 模型最后一段自然语言总结（无则空串）。 */
  finalText: string;
}

export interface RunOptions {
  task: string;
  sessionId: string;
  apiKey: string;
  recorder: SessionRecorder;
  maxSteps?: number;
  signal?: AbortSignal;
  /**
   * 模型覆盖，缺省用 buildModel()。
   *
   * 存在的理由是可测性：pi 自带 faux provider（registerFauxProvider）可以按脚本
   * 回放固定的 assistant 消息，据此在**不消耗网关配额、不需要 QA_API_KEY** 的前提下
   * 验证循环装配、工具执行、步数上限与「后端不可达时 agent 不崩溃」这些与 LLM 无关的
   * 行为。生产路径不传此参数。
   */
  model?: Model<any>;
}

/** 把工具入参压成一行，供控制台逐步打印（长参数截断，完整入参在 jsonl 与后端 trace 里）。 */
function formatArgs(args: unknown): string {
  const text = JSON.stringify(args ?? {});
  return text.length > 160 ? `${text.slice(0, 160)}…` : text;
}

export async function runAgent(options: RunOptions): Promise<RunResult> {
  const { task, sessionId, apiKey, recorder, signal } = options;
  const maxSteps = options.maxSteps ?? MAX_STEPS;

  if (TOOL_MODE !== "native") {
    // prompt 兜底模式尚未实现（网关 function-calling 能力未实测，见 README「网关能力验证」）。
    // 这里显式失败而不是静默按 native 跑，避免运行结果与所选模式不符。
    throw new Error(
      `AGENT_TOOL_MODE=${TOOL_MODE} 尚未实现：当前仅支持 native（网关原生 function-calling）。` +
      "prompt 兜底模式待网关能力实测后按结论补齐，详见 agent-runner/README.md。",
    );
  }

  const toolCalls: ToolCallLog[] = [];
  // 已完成的 turn 数；工具在第 step+1 个 turn 内执行（turn_end 才递增 step）。
  let step = 0;

  const tools = buildTools(sessionId, (entry) => {
    toolCalls.push(entry);
    recorder.write({
      type: "tool_call",
      step: step + 1,
      seq: entry.seq,
      tool: entry.tool,
      params: entry.params,
      summary: entry.summary,
      is_error: entry.isError,
    });
  });

  const context: AgentContext = {
    systemPrompt: loadSystemPrompt(),
    messages: [],
    tools,
  };

  const prompts: AgentMessage[] = [{ role: "user", content: task, timestamp: Date.now() }];

  let stopReason: RunStopReason = "completed";
  let errorMessage: string | undefined;
  let finalText = "";

  const emit = (event: AgentEvent): void => {
    switch (event.type) {
      case "tool_execution_start":
        console.log(`  → ${event.toolName} ${formatArgs(event.args)}`);
        break;
      case "tool_execution_end": {
        const record = toolCalls[toolCalls.length - 1];
        const summary = record && !event.isError ? record.summary : String(event.result?.content?.[0]?.text ?? "");
        console.log(`  ${event.isError ? "✗" : "←"} ${event.toolName}: ${summary.slice(0, 300)}`);
        break;
      }
      case "turn_end": {
        const message = event.message;
        if (message.role !== "assistant") break;
        step += 1;
        const text = message.content
          .filter((block): block is { type: "text"; text: string } => block.type === "text")
          .map((block) => block.text)
          .join("")
          .trim();
        if (text) {
          finalText = text;
          console.log(`\n[第 ${step} 步] ${text.slice(0, 600)}`);
        }
        if (message.stopReason === "error" || message.stopReason === "aborted") {
          stopReason = message.stopReason === "aborted" ? "aborted" : "model_error";
          errorMessage = message.errorMessage;
        }
        recorder.write({
          type: "turn_end",
          step,
          text,
          stop_reason: message.stopReason,
          tool_call_count: message.content.filter((block) => block.type === "toolCall").length,
        });
        break;
      }
      default:
        break;
    }
  };

  const model = options.model ?? buildModel();
  console.log(`\n[agent] 模型=${model.id === QA_MODEL ? QA_MODEL : `${model.id}（覆盖）`} 工具模式=${TOOL_MODE} 步数上限=${maxSteps}`);

  await runAgentLoop(
    prompts,
    context,
    {
      model,
      apiKey,
      convertToLlm: (messages) => messages as Message[],
      // 每个 turn 收束后判定：达上限即正常收尾，不再发起下一次 LLM 调用。
      shouldStopAfterTurn: () => {
        if (step < maxSteps) return false;
        stopReason = "max_steps";
        return true;
      },
    },
    emit,
    signal,
  );

  return { steps: step, stopReason, errorMessage, toolCalls, finalText };
}
=====smoke.ts=====
/**
 * CLI 冒烟入口：端到端跑一次多步布置任务。
 *
 *   npm run smoke -- "布置塔吊、办公区、钢筋加工棚、消防通道，办公区远离基坑，完成后校核并修复问题"
 *
 * 流程：读 scenes/demo.json → 建后端会话 → 跑 agent 循环 → 逐步打印工具调用与
 * 观测摘要 → 打印最终 validate 与 diff → 删除会话。
 *
 * 退出码：0 = 跑通（无论校核是否全绿，那是布置质量问题不是脚本失败）；
 * 1 = 无法开跑或运行中断（缺 KEY / 后端不可达 / 模型报错）。
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { runAgent } from "./agent.js";
import { callTool, createSession, deleteSession, getTrace } from "./backendClient.js";
import { BACKEND_URL, MAX_STEPS, QA_MODEL, requireApiKey } from "./config.js";
import { SessionRecorder, newRunId } from "./sessionLog.js";

const PACKAGE_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));

const DEFAULT_TASK =
  "布置塔吊、办公区、钢筋加工棚、消防通道，办公区远离基坑，完成后校核并修复问题";

interface DemoScene {
  scene: Record<string, unknown>;
  milestones: Array<Record<string, unknown>>;
}

function loadScene(): DemoScene {
  const path = join(PACKAGE_ROOT, "scenes", "demo.json");
  return JSON.parse(readFileSync(path, "utf8")) as DemoScene;
}

function line(char = "─"): void {
  console.log(char.repeat(72));
}

async function main(): Promise<number> {
  const task = process.argv.slice(2).join(" ").trim() || DEFAULT_TASK;
  // 缺 KEY 时 requireApiKey 打印降级提示并退出（非堆栈）。
  const apiKey = requireApiKey();

  const demo = loadScene();
  const runId = newRunId();
  const recorder = new SessionRecorder(runId);

  line("═");
  console.log(`任务：${task}`);
  console.log(`后端：${BACKEND_URL}   模型：${QA_MODEL}   步数上限：${MAX_STEPS}`);
  console.log(`会话记录：${recorder.filePath}`);
  line("═");

  let sessionId: string;
  try {
    sessionId = await createSession(demo.scene, demo.milestones);
  } catch (error) {
    // 后端不可达是最常见的开跑失败原因，给出可行动提示而不是堆栈。
    console.error(`\n无法创建智能体会话：${(error as Error).message}`);
    return 1;
  }
  console.log(`会话 id：${sessionId}\n`);

  recorder.write({
    type: "run_start",
    run_id: runId,
    backend_session_id: sessionId,
    model: QA_MODEL,
    task,
    max_steps: MAX_STEPS,
  });

  let exitCode = 0;
  try {
    const result = await runAgent({ task, sessionId, apiKey, recorder, maxSteps: MAX_STEPS });

    line();
    console.log(`循环结束：${result.steps} 步，终止原因=${result.stopReason}` +
      (result.errorMessage ? `（${result.errorMessage}）` : ""));

    // 收尾观测：无论模型是否自行调用过，都独立取一次最终校核与 diff 作为客观结论。
    let finalValid: boolean | undefined;
    let issueCount: number | undefined;
    let changeCount: number | undefined;
    try {
      const validation = (await callTool(sessionId, "validate", {})).result as {
        valid: boolean;
        issues: Array<{ severity: string; code: string; message: string }>;
      };
      finalValid = validation.valid;
      issueCount = validation.issues.length;
      line();
      console.log(`最终校核：${validation.valid ? "通过" : `发现 ${validation.issues.length} 个问题`}`);
      for (const issue of validation.issues) {
        console.log(`  [${issue.severity}] ${issue.code} ${issue.message}`);
      }

      const diff = (await callTool(sessionId, "diff", {})).result as {
        changes: Array<{ change: string; name: string }>;
        earthworks: unknown[];
        crane_actions: unknown[];
      };
      changeCount = diff.changes.length;
      console.log(`\n最终 diff：${diff.changes.length} 处对象变更，` +
        `土方 ${diff.earthworks.length} 项，塔吊动作 ${diff.crane_actions.length} 项`);
      for (const change of diff.changes) {
        console.log(`  ${change.change}  ${change.name}`);
      }
    } catch (error) {
      console.error(`收尾观测失败：${(error as Error).message}`);
      exitCode = 1;
    }

    // 工具调用总览：seq 来自后端 trace，与服务端序号一一对应。
    line();
    console.log(`工具调用共 ${result.toolCalls.length} 次：`);
    for (const call of result.toolCalls) {
      console.log(`  seq=${call.seq ?? "-"} ${call.isError ? "✗" : "✓"} ${call.tool} — ${call.summary.slice(0, 120)}`);
    }

    try {
      const trace = await getTrace(sessionId);
      console.log(`\n后端 trace 条目：${trace.entries.length}`);
    } catch (error) {
      console.error(`读取后端 trace 失败：${(error as Error).message}`);
    }

    if (result.finalText) {
      line();
      console.log(`智能体总结：\n${result.finalText}`);
    }

    recorder.write({
      type: "run_end",
      steps: result.steps,
      stop_reason: result.stopReason,
      error_message: result.errorMessage,
      final_valid: finalValid,
      issue_count: issueCount,
      diff_change_count: changeCount,
    });

    if (result.stopReason === "model_error") exitCode = 1;
  } catch (error) {
    console.error(`\n运行失败：${(error as Error).message}`);
    recorder.write({ type: "run_end", steps: 0, stop_reason: "failed", error_message: (error as Error).message });
    exitCode = 1;
  } finally {
    // 会话是后端内存资源，无论成败都要释放；删除失败只告警不改变退出码。
    try {
      await deleteSession(sessionId);
      console.log(`\n已删除会话 ${sessionId}`);
    } catch (error) {
      console.error(`删除会话失败（将由 TTL 回收）：${(error as Error).message}`);
    }
    line("═");
    console.log(`会话记录已落盘：${recorder.filePath}`);
  }

  return exitCode;
}

process.exitCode = await main();

/**
 * 工具桥：把 P1 工具面的每个工具注册为 pi 自定义工具。
 *
 * 红线：入参 Schema 与后端 LayoutIntent 对齐，全部是相对关系语义
 * （anchor/reference/side/distance），不含任何坐标字段；坐标一律由
