  Type.Literal("office"), Type.Literal("rebar_yard"), Type.Literal("fire_lane"),
  Type.Literal("temporary"), Type.Literal("fence"), Type.Literal("road"),
], { description: "对象类型：tower_crane=塔吊 excavation=基坑 excavator=挖掘机 office=办公区 rebar_yard=钢筋加工棚 fire_lane=消防通道 temporary=材料堆场 fence=围挡 road=施工道路" });

const ANCHOR = Type.Union([
  Type.Literal("north"), Type.Literal("south"), Type.Literal("east"), Type.Literal("west"),
  Type.Literal("northeast"), Type.Literal("northwest"), Type.Literal("southeast"),
  Type.Literal("southwest"), Type.Literal("center"),
], { description: "场地方位（北=north）" });

const SIZE = Type.Object({
  width: Type.Number({ description: "宽（米）" }),
  depth: Type.Number({ description: "深（米）" }),
});

const PLACEMENT = Type.Object({
  kind: KIND,
  count: Type.Optional(Type.Number({ description: "数量，默认 1，最多 5" })),
  name: Type.Optional(Type.String({ description: "自定义名称（可选）" })),
  size: Type.Optional(SIZE),
  anchor: Type.Optional(ANCHOR),
  relation: Type.Optional(Type.Union([Type.Literal("near"), Type.Literal("along_edge")], {
    description: "near=靠近某参照对象；along_edge=沿场地边布置",
  })),
  reference_id: Type.Optional(Type.String({ description: "参照对象 id（须来自 scene_snapshot 观测；本轮新建对象用 @类型 如 @excavation）" })),
  side: Type.Optional(ANCHOR),
  distance_m: Type.Optional(Type.Number({ description: "与参照对象的间距（米）" })),
  rotation_y: Type.Optional(Type.Number({ description: "旋转角度（度）" })),
  phase_rank: Type.Optional(Type.Number({ description: "所属施工阶段 rank" })),
