/** 每次工具调用的记录：seq 取自后端 trace，保证 pi 侧 jsonl 与服务端序号可对齐。 */
export interface ToolCallLog {
  /** 后端 trace 序号；调用未落到后端（如后端不可达）时为 null。 */
  seq: number | null;
  tool: string;
  params: Record<string, unknown>;
  summary: string;
  isError: boolean;
}

/** 调用记录回调：由调用方决定落 jsonl 还是仅收集。 */
export type ToolCallSink = (entry: ToolCallLog) => void;

export function buildTools(sessionId: string, onCall: ToolCallSink): AgentTool[] {
  /**
   * 统一执行封装：HTTP 调用 + 记录。
   *
   * 后端不可达 / 返回错误时抛 Error——pi 的 executePreparedToolCall 会捕获它并
   * 转成 isError 的工具结果回给模型（见 agent-loop.js），进程不崩溃，模型据此
   * 换策略或如实报告。这是「后端未启动时 agent 不崩溃」的落点。
   */
  function bridge(name: string, description: string, parameters: TSchema, summarize: (result: any) => string): AgentTool {
    return {
      name,
      label: name,
      description,
      parameters,
      executionMode: "sequential",
      execute: async (_toolCallId, params) => {
        try {
          const response = await callTool(sessionId, name, (params ?? {}) as Record<string, unknown>);
          const summary = summarize(response.result);
          onCall({ seq: response.seq, tool: name, params: params as Record<string, unknown>, summary, isError: false });
          return {
            content: [{ type: "text", text: JSON.stringify(response.result, null, 1) }],
            details: { seq: response.seq },
          };
        } catch (error) {
          const message = (error as Error).message;
          onCall({ seq: null, tool: name, params: params as Record<string, unknown>, summary: message, isError: true });
          throw new Error(message);
        }
      },
    };
  }

  return [
    bridge(
      "scene_snapshot",
      "查看当前场地布置的完整观测：场地尺寸、施工阶段、全部对象（id/名称/类型/位置/尺寸）、已解析约束。规划布置前、需要引用对象 id 时、怀疑场景状态与预期不符时调用。无入参。",
      Type.Object({}),
      (result) => result.summary ?? "",
    ),
    bridge(
      "apply_intent",
      "提交结构化布置意图（放置/移动/删除/修改/挖基坑/回填/塔吊动作），由后端确定性求解器计算具体位置并落到会话场景。你只描述『放什么、相对哪里』，绝不给坐标。一次可提交多条需求；返回实际落位动作、土方区域与自动校核结果。返回的 notes 里若有『未找到可行位置』说明该条被跳过，需换方位或参照重试。",
      APPLY_INTENT_PARAMS,
      (result) => `落位 ${result.actions?.length ?? 0} 个动作，土方 ${result.earthworks?.length ?? 0} 项，校核 ${result.validation?.valid ? "通过" : `发现 ${result.validation?.issues?.length ?? 0} 个问题`}`,
    ),
    bridge(
      "validate",
      "对当前会话场景执行总平面规则校核（红线越界/占地重叠/塔吊-基坑净距/消防通道净宽/办公区与作业区隔离）。每次 apply_intent 后必须调用；返回 issues 列表（severity=error 必须修复，warning 酌情）。无入参。",
      Type.Object({}),
      (result) => (result.valid ? "校核通过" : `发现 ${result.issues?.length ?? 0} 个问题`),
    ),
    bridge(
      "diff",
      "查看会话场景相对初始快照的全部变更（新增/移动/删除/修改的对象、土方区域、塔吊动作）。任务收尾汇报前调用，向用户说明改了什么。无入参。",
      Type.Object({}),
      (result) => `${result.changes?.length ?? 0} 处对象变更，土方 ${result.earthworks?.length ?? 0} 项`,
    ),
    bridge(
      "reset_to_checkpoint",
      "回滚会话场景到指定检查点并丢弃其后的修改。0 号为初始快照；每次 apply_intent 成功后自动产生一个新检查点（编号见其返回的 checkpoint_id）。仅当某次布置整体走错、逐条修复代价过高时使用。",
      Type.Object({ checkpoint_id: Type.Number({ description: "目标检查点编号" }) }),
      (result) => result.note ?? "",
    ),
  ];
}
