/**
 * P1 工具面的 HTTP 客户端：建会话 / 统一工具调用 / 读服务端 trace。
 *
 * 后端不可达或返回错误时抛出带业务语义的 Error（由工具桥捕获后
 * 以 isError 工具结果回给内核），绝不让进程崩溃。
 */
import { BACKEND_URL } from "./config.js";

export interface ToolCallResponse {
  tool: string;
  seq: number;
  duration_ms: number;
  result: Record<string, unknown>;
}

async function request(path: string, init?: RequestInit): Promise<unknown> {
  let response: Response;
  try {
    response = await fetch(`${BACKEND_URL}${path}`, {
      headers: { "Content-Type": "application/json" },
      ...init,
    });
  } catch (error) {
    throw new Error(
      `后端服务不可达（${BACKEND_URL}）：请确认 FastAPI 已在该地址启动` +
      "（backend 目录下 .venv/bin/python run.py；换端口用 AGENT_BACKEND_URL 覆盖）。" +
      `原因：${(error as Error).message}`,
    );
  }
  const body = await response.text();
  let parsed: unknown;
  try {
    parsed = body ? JSON.parse(body) : {};
  } catch {
    throw new Error(`后端返回非 JSON 响应（HTTP ${response.status}）：${body.slice(0, 200)}`);
  }
  if (!response.ok) {
    const detail = (parsed as { detail?: string }).detail ?? body.slice(0, 200);
    throw new Error(`后端返回错误（HTTP ${response.status}）：${detail}`);
  }
  return parsed;
}

export async function createSession(scene: unknown, milestones: unknown[]): Promise<string> {
  const data = (await request("/api/agent/sessions", {
    method: "POST",
    body: JSON.stringify({ scene, milestones }),
  })) as { id: string };
  return data.id;
}

export async function deleteSession(sessionId: string): Promise<void> {
  await request(`/api/agent/sessions/${sessionId}`, { method: "DELETE" });
}

export async function callTool(
  sessionId: string,
  tool: string,
  params: Record<string, unknown>,
): Promise<ToolCallResponse> {
  return (await request(`/api/agent/sessions/${sessionId}/tools/${tool}`, {
    method: "POST",
    body: JSON.stringify({ params }),
  })) as ToolCallResponse;
}

export async function getTrace(sessionId: string): Promise<{ entries: Array<Record<string, unknown>> }> {
  return (await request(`/api/agent/sessions/${sessionId}/trace`)) as { entries: Array<Record<string, unknown>> };
}

# 角色

你是施工场地布置智能体。用户给出一段施工组织要求，你通过循环调用工具，把要求分解为多步布置操作并逐步完成，直到场地布置满足要求且规则校核通过。

# 工作方式

1. 先调用 scene_snapshot 了解场地现状（尺寸、阶段、既有对象及其 id）。
2. 把用户要求分解为若干条布置意图，用 apply_intent 提交。可一次提交多条相关需求（如先挖基坑、再在其旁布塔吊，用 @excavation 引用本轮新建的基坑）。
3. 每次 apply_intent 之后必须调用 validate 校核。
4. 校核结果中的 error 必须处理：调整意图（换方位、换参照、拉开间距）后重新 apply_intent 或 reset_to_checkpoint 回滚重来；连续尝试仍无法修复时，明确报告哪条要求无法满足及原因，不得假装完成。warning 尽量消除，无法消除时在总结中说明。
5. 收尾时调用 diff 汇总全部变更，并用一段中文向用户报告：完成了什么、校核结论、遗留问题。

# 红线（违反即错误）

- 你只能通过工具调用操作场景；只输出工具调用与结构化意图。
- 禁止臆造坐标或任何具体位置数值：位置一律由后端求解器计算，你只描述"放什么、相对哪里"（方位/参照/间距语义）。
- 禁止臆造对象 id：id 只能来自 scene_snapshot / apply_intent / diff 的观测结果，或 @类型 引用本轮新建对象。
- 每次布置（apply_intent）后必须 validate；有 error 必须尝试修复或明确报告无法修复。

# 终止条件（满足任一即结束）

- 所有要求已落实且 validate 通过（无 error）：调用 diff 后向用户总结，结束。
- 达到步数上限：立即用当前状态总结，说明已完成与未完成的部分。
- 判断任务不可完成（如场地过小放不下）：说明原因与已尽的尝试，结束，不得硬塞违规布置。
