/**
 * pi 侧会话记录：每次 run 落一份 jsonl 到 agent-runner/sessions/（已 gitignore）。
 *
 * 与后端 trace 的对齐方式：每条 tool_call 记录带上后端返回的 seq
 * （即 /api/agent/sessions/{id}/trace 里同一条目的序号）。后端调用失败时
 * 没有 seq（请求根本没落到 trace 上），此时记 null 并置 is_error，
 * 避免用本地序号冒充服务端序号造成两侧错位。
 */
import { appendFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SESSIONS_DIR = join(dirname(dirname(fileURLToPath(import.meta.url))), "sessions");

export type SessionRecord =
  | { type: "run_start"; run_id: string; backend_session_id: string; model: string; task: string; max_steps: number }
  | { type: "turn_end"; step: number; text: string; stop_reason: string; tool_call_count: number }
  | { type: "tool_call"; step: number; seq: number | null; tool: string; params: unknown; summary: string; is_error: boolean }
  | { type: "run_end"; steps: number; stop_reason: string; error_message?: string; final_valid?: boolean; issue_count?: number; diff_change_count?: number };

/** 一次 run 的 jsonl 记录器；构造即建目录并写下首条 run_start。 */
export class SessionRecorder {
  readonly runId: string;
  readonly filePath: string;

  constructor(runId: string) {
    this.runId = runId;
    mkdirSync(SESSIONS_DIR, { recursive: true });
    this.filePath = join(SESSIONS_DIR, `${runId}.jsonl`);
  }

  write(record: SessionRecord): void {
    appendFileSync(this.filePath, `${JSON.stringify({ ts: Date.now(), ...record })}\n`, "utf8");
  }
}

/** run 标识：时间戳 + 随机后缀，便于按时间排序且不会并发覆盖。 */
export function newRunId(): string {
  const stamp = new Date().toISOString().replace(/[-:]/g, "").replace(/\..+$/, "");
  return `run-${stamp}-${Math.random().toString(36).slice(2, 8)}`;
}

