/**
 * 首个验证点：实测 QA 网关是否支持 tools / function-calling。
 *
 * 两步实测：
 * 1. 原始 HTTP：直接向 {QA_API_URL}/chat/completions POST 带 tools 的请求，
 *    观察响应是否含 tool_calls（网关层面是否透传 OpenAI tools 协议）；
 * 2. pi-ai 链路：用 buildModel() 的 compat 配置走 complete()，确认 pi 侧
 *    能解析出 toolCall 内容块（端到端可用性）。
 *
 * 结论须写入 README「网关能力验证」节。若实测不支持，则需先补齐 prompt 兜底模式
 * （提示词式 JSON 工具调用 + 严格 Schema 解析），再把 AGENT_TOOL_MODE 切过去——
 * 该模式**当前尚未实现**，因为选哪种兜底写法取决于本探针的实测结论
 * （模型是否会稳定吐出可解析的 JSON、是否需要 response_format）。
 */
import { complete, type Context, Type } from "@mariozechner/pi-ai";
import { buildModel, QA_API_URL, QA_MODEL, requireApiKey } from "./config.js";

const PROBE_TOOL = {
  name: "get_site_size",
  description: "查询施工场地的宽度与深度（米）。回答场地尺寸问题时必须调用本工具。",
  parameters: {
    type: "object",
    properties: {
      unit: { type: "string", enum: ["m"], description: "长度单位，固定为米" },
    },
    required: [],
  },
};

async function probeRawHttp(apiKey: string): Promise<void> {
  console.log(`\n[1/2] 原始 HTTP 探测 ${QA_API_URL}/chat/completions（model=${QA_MODEL}）`);
  const response = await fetch(`${QA_API_URL}/chat/completions`, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: QA_MODEL,
      messages: [{ role: "user", content: "施工场地有多大？请使用工具查询。" }],
      tools: [{ type: "function", function: PROBE_TOOL }],
      tool_choice: "auto",
      max_tokens: 512,
    }),
  });
  console.log(`HTTP ${response.status}`);
  const body = await response.text();
  let parsed: any;
  try {
    parsed = JSON.parse(body);
  } catch {
    console.log("响应非 JSON：", body.slice(0, 500));
    return;
  }
  const message = parsed?.choices?.[0]?.message;
  console.log("finish_reason:", parsed?.choices?.[0]?.finish_reason);
  console.log("message.tool_calls:", JSON.stringify(message?.tool_calls ?? null));
  console.log("message.content 摘要:", String(message?.content ?? "").slice(0, 200));
  if (message?.tool_calls?.length) {
    console.log("=> 网关支持原生 function-calling ✓");
  } else {
    console.log("=> 未返回 tool_calls；网关可能不支持或模型未选择调用（结合内容判断）");
  }
}

async function probeViaPi(apiKey: string): Promise<void> {
  console.log("\n[2/2] pi-ai complete() 链路探测（compat 见 config.ts）");
  const context: Context = {
    systemPrompt: "你是施工助手。回答场地尺寸问题必须调用 get_site_size 工具，禁止凭空回答。",
    messages: [{ role: "user", content: "施工场地有多大？", timestamp: Date.now() }],
    tools: [{
      name: PROBE_TOOL.name,
      description: PROBE_TOOL.description,
      parameters: Type.Object({}),
    }],
  };
  const message = await complete(buildModel(), context, { apiKey });
  console.log("stopReason:", message.stopReason, message.errorMessage ? `error=${message.errorMessage}` : "");
  for (const block of message.content) {
    if (block.type === "toolCall") {
      console.log(`toolCall: ${block.name}(${JSON.stringify(block.arguments)})`);
    } else if (block.type === "text") {
      console.log("text 摘要:", block.text.slice(0, 200));
    }
  }
  const hasToolCall = message.content.some((block) => block.type === "toolCall");
  console.log(hasToolCall ? "=> pi 链路可解析 toolCall ✓" : "=> pi 链路未产生 toolCall");
}

const apiKey = requireApiKey();
await probeRawHttp(apiKey);
await probeViaPi(apiKey);

