    log(`  ⓘ 自动校核：${validation.valid ? "通过" : `发现 ${issues.length} 个问题`}`);
    const observation = validation.valid
      ? "【自动校核】通过，无规则问题。"
      : `【自动校核】发现 ${issues.length} 个问题：\n${
          issues.map((issue) => `- [${issue.severity}] ${issue.code} ${issue.message}`).join("\n")
        }`;
    return {
      content: [...toolContext.result.content, { type: "text" as const, text: observation }],
    };
  };

  const model = options.model ?? buildModel();
  log(`\n[agent] 模型=${model.id === QA_MODEL ? QA_MODEL : `${model.id}（覆盖）`} 工具模式=${TOOL_MODE} 步数上限=${maxSteps}`);

  await runAgentLoop(
    prompts,
    context,
    {
      model,
      apiKey,
      convertToLlm: (messages) => messages as Message[],
      afterToolCall,
      // 每个 turn 收束后判定：达上限即正常收尾，不再发起下一次 LLM 调用。
      shouldStopAfterTurn: () => {
        if (step < maxSteps) return false;
        stopReason = "max_steps";
        return true;
      },
    },
    emit,
    signal,
  );"}

{"file_path": "/Users/[USER]/Documents/wt-lr05-p5/agent-runner/src/planner.ts", "content": "/**
 * 计划生成：把用户任务转成一份业务语言的步骤清单，供用户批准后再执行。
 *
 * 为什么与执行循环分开而不是让 agent 自己先"说计划再干活"：批准是**人的决策点**，
 * 需要在任何场景改动发生之前完成。若交给循环内部，模型完全可能先调一次
 * apply_intent 再报计划，届时批准与否都已经晚了。故计划走一次独立的
 * **无工具** complete() 调用——没有工具就绝不可能碰到场景。
 *
 * 计划只描述"打算做什么"，不含坐标（轨道红线 1），也不绑定具体工具名——
 * 用户看的是施工语言的步骤，不是工具调用序列。
 */
import { complete, type Context } from "@mariozechner/pi-ai";
import { buildModel } from "./config.js";
import { callTool } from "./backendClient.js";

export interface PlanStep {
  title: string;
  detail: string;
}

const PLAN_SYSTEM_PROMPT = `你是施工场地布置智能体的规划环节。用户给出一段施工组织要求，你只负责列出打算怎么做的步骤清单，供用户审批。

要求：
- 输出 3 到 6 步，每步一句话说清"做什么"，用施工业务语言（如"在场地西南角布置办公区，与基坑保持安全距离"）。
- 第一步通常是整场布置：用整场求解一次性铺出全部对象；后续步骤是评估与局部返工。
- 禁止出现任何坐标、米制位置数值（间距、尺寸这类要求可以写）。
- 禁止出现工具名、接口名、字段名等技术术语。
- 严格输出 JSON，不要 markdown 代码块，格式为：
{"steps":[{"title":"简短标题","detail":"一句话说明"}]}`;

/** 从模型回复里取出 JSON：模型偶尔会裹 markdown 代码块或加一句前言。 */
function extractJson(text: string): unknown {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = (fenced ? fenced[1] : text).trim();
  const start = candidate.indexOf("{");
  const end = candidate.lastIndexOf("}");
  if (start < 0 || end <= start) throw new Error("计划响应中未找到 JSON 对象");
  return JSON.parse(candidate.slice(start, end + 1));
}

/**
 * 产出计划。会先取一次场景观测让计划贴合实际场地（尺寸、既有对象），
 * 观测失败不阻塞——没有观测也能给出合理的通用步骤，比直接失败强。
 */
export async function makePlan(options: {
  task: string;
  sessionId: string;
  apiKey: string;
  signal?: AbortSignal;
}): Promise<PlanStep[]> {
  let sceneNote = "";
  try {
    const snapshot = (await callTool(options.sessionId, "scene_snapshot", {})).result as { summary?: string };
    if (snapshot.summary) sceneNote = `\n\n当前场地观测：${snapshot.summary}`;
  } catch {
    // 观测拿不到就按通用流程规划，不因此让整次任务失败。
  }

  const context: Context = {
    systemPrompt: PLAN_SYSTEM_PROMPT,
    messages: [{ role: "user", content: `${options.task}${sceneNote}`, timestamp: Date.now() }],
  };
  const message = await complete(buildModel(), context, { apiKey: options.apiKey, signal: options.signal });
  if (message.stopReason === "error") {
    throw new Error(message.errorMessage ?? "推理网关调用失败");
  }
  const text = message.content
    .filter((block): block is { type: "text"; text: string } => block.type === "text")
    .map((block) => block.text)
    .join("")
    .trim();
  if (!text) throw new Error("推理服务未返回计划内容");

  const parsed = extractJson(text) as { steps?: Array<{ title?: unknown; detail?: unknown }> };
  const steps = (parsed.steps ?? [])
    .map((item) => ({
      title: String(item.title ?? "").trim(),
      detail: String(item.detail ?? "").trim(),
    }))
    .filter((item) => item.title);
  if (!steps.length) throw new Error("推理服务返回的计划为空");
  return steps;
}
"}

