{"file_path": "/Users/[USER]/Documents/wt-lr05-p5/agent-runner/src/server.ts", "content": "/**
 * sidecar 常驻 HTTP 服务：把 P1 的 CLI 逻辑（runAgent）暴露成后端可转发的两个端点。
 *
 *   npm run serve      # 监听 AGENT_RUNNER_PORT（默认 8100）
 *
 * 端点：
 * - `GET  /health`   健康探针，返回模型与密钥就绪情况（不回显密钥本身）。
 * - `POST /plan`     产出计划步骤清单，一次性 JSON 响应。**不碰场景**（无工具调用）。
 * - `POST /execute`  执行循环，响应体为 **JSONL 流**：每行一条进度事件，
 *                    后端逐行读取并转成 SSE 推给前端。
 *
 * 为什么 /execute 用 JSONL 而不是 SSE：这条链路的消费者只有后端 run_service
 * （httpx `iter_lines`），JSONL 一行一事件即可，无需 SSE 的事件名/注释行语法。
 * 面向浏览器的 SSE 由后端那一段负责，协议在它该在的边界上转换。
 *
 * 中止语义：后端中止或判定停滞时**直接断开这条连接**。Node 在客户端断开时给
 * response 发 "close"，我们据此 abort 循环——因此中止不需要额外的控制端点，
 * 也不会出现"后端已经不听了、这边还在烧网关配额"的情况。
 *
 * 无鉴权、只监听本机：sidecar 是后端的内部依赖，不面向公网。若将来需要跨主机
 * 部署，须先补鉴权再放开监听地址。
 */
import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
import { runAgent } from "./agent.js";
import { MAX_STEPS, QA_API_KEY, QA_MODEL, RUNNER_HOST, RUNNER_PORT, requireApiKey } from "./config.js";
import { makePlan } from "./planner.js";
import { SessionRecorder, newRunId } from "./sessionLog.js";

interface PlanRequestBody {
  session_id?: string;
  task?: string;
}

interface ExecuteRequestBody {
  session_id?: string;
  task?: string;
  max_steps?: number;
  plan?: Array<{ title?: string; detail?: string }>;
}

const BODY_LIMIT_BYTES = 1_000_000;

async function readJsonBody(request: IncomingMessage): Promise<Record<string, unknown>> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of request) {
    size += (chunk as Buffer).length;
    // 请求体来自本机后端，超限只可能是异常调用；早失败好过把内存吃满。
    if (size > BODY_LIMIT_BYTES) throw new Error("请求体过大");
    chunks.push(chunk as Buffer);
  }
  const raw = Buffer.concat(chunks).toString("utf8");
  if (!raw) return {};
  return JSON.parse(raw) as Record<string, unknown>;
}

function sendJson(response: ServerResponse, status: number, payload: unknown): void {
  const body = JSON.stringify(payload);
  response.writeHead(status, { "Content-Type": "application/json; charset=utf-8" });
  response.end(body);
}

function log(message: string): void {
  console.log(`[${new Date().toISOString()}] ${message}`);
}

async function handlePlan(request: IncomingMessage, response: ServerResponse): Promise<void> {
  const body = (await readJsonBody(request)) as PlanRequestBody;
  const sessionId = String(body.session_id ?? "").trim();
  const task = String(body.task ?? "").trim();
  if (!sessionId || !task) {
    sendJson(response, 400, { detail: "缺少 session_id 或 task" });
    return;
  }
  log(`/plan session=${sessionId} task=${task.slice(0, 60)}`);
  try {
    const steps = await makePlan({ task, sessionId, apiKey: requireApiKey() });
    log(`/plan 产出 ${steps.length} 步`);
    sendJson(response, 200, { steps });
  } catch (error) {
    log(`/plan 失败：${(error as Error).message}`);
    sendJson(response, 502, { detail: `产出计划失败：${(error as Error).message}` });
  }
}

async function handleExecute(request: IncomingMessage, response: ServerResponse): Promise<void> {
  const body = (await readJsonBody(request)) as ExecuteRequestBody;
  const sessionId = String(body.session_id ?? "").trim();
  const task = String(body.task ?? "").trim();
  if (!sessionId || !task) {
    sendJson(response, 400, { detail: "缺少 session_id 或 task" });
    return;
  }
  const maxSteps = Number(body.max_steps ?? MAX_STEPS);
  const plan = (body.plan ?? [])
    .map((item) => ({ title: String(item.title ?? "").trim(), detail: String(item.detail ?? "").trim() }))
    .filter((item) => item.title);

  response.writeHead(200, {
    "Content-Type": "application/x-ndjson; charset=utf-8",
    "Cache-Control": "no-cache",
    // 逐行即时送达，中间层不得缓冲——缓冲会让进度整批堆到最后才出现。
    "X-Accel-Buffering": "no",
  });

  const write = (event: Record<string, unknown>): void => {
    if (response.writableEnded) return;
    response.write(`${JSON.stringify(event)}\n`);
  };

  // 后端断开连接即中止循环（中止与停滞判定都走这条路径，见文件头说明）。
  const controller = new AbortController();
  let disconnected = false;
  const onClose = (): void => {
    if (response.writableFinished) return;
    disconnected = true;
    log(`/execute session=${sessionId} 连接断开，中止循环`);
    controller.abort();
  };
  request.on("close", onClose);

  const recorder = new SessionRecorder(newRunId());
  log(`/execute session=${sessionId} maxSteps=${maxSteps} plan=${plan.length} 步`);
  recorder.write({
    type: "run_start",
    run_id: recorder.runId,
    backend_session_id: sessionId,
    model: QA_MODEL,
    task,
    max_steps: maxSteps,
  });

  try {
    const result = await runAgent({
      task,
      sessionId,
      apiKey: requireApiKey(),
      recorder,
      maxSteps,
      plan,
      quiet: true,
      signal: controller.signal,
      onProgress: (event) => write(event as unknown as Record<string, unknown>),
    });
    recorder.write({
      type: "run_end",
      steps: result.steps,
      stop_reason: result.stopReason,
      error_message: result.errorMessage,
    });
    if (disconnected) return;
    log(`/execute 结束：${result.steps} 步，stopReason=${result.stopReason}`);
    if (result.stopReason === "model_error") {
      write({ type: "run_failed", message: `推理服务调用失败：${result.errorMessage ?? "未知原因"}` });
    } else {
      write({
        type: "run_finished",
        stop_reason: result.stopReason === "max_steps" ? "max_steps" : "completed",
        steps: result.steps,
        message: result.finalText || "智能体已结束本次任务。",
      });
    }
  } catch (error) {
    // 中止是正常收束路径：后端已经不在听了，不必再往断开的连接上写。
    if (disconnected || controller.signal.aborted) {
      recorder.write({ type: "run_end", steps: 0, stop_reason: "aborted" });
    } else {
      log(`/execute 异常：${(error as Error).message}`);
      recorder.write({ type: "run_end", steps: 0, stop_reason: "failed", error_message: (error as Error).message });
      write({ type: "run_failed", message: (error as Error).message });
    }
  } finally {
    request.off("close", onClose);
    if (!response.writableEnded) response.end();
  }
}

const server = createServer((request, response) => {
  const url = request.url ?? "";
  const route = url.split("?")[0];

  if (request.method === "GET" && route === "/health") {
    sendJson(response, 200, {
      status: "ok",
      model: QA_MODEL,
      max_steps: MAX_STEPS,
      // 只报是否配置，绝不回显密钥。
      api_key_configured: Boolean(QA_API_KEY),
    });
    return;
  }

  const handler = request.method === "POST" && route === "/plan" ? handlePlan
    : request.method === "POST" && route === "/execute" ? handleExecute
    : null;

  if (!handler) {
    sendJson(response, 404, { detail: `未知路由：${request.method} ${route}` });
    return;
  }

  handler(request, response).catch((error: Error) => {
    log(`处理 ${route} 时未捕获异常：${error.message}`);
    if (!response.headersSent) sendJson(response, 500, { detail: error.message });
    else if (!response.writableEnded) response.end();
  });
});

server.listen(RUNNER_PORT, RUNNER_HOST, () => {
  log(`agent-runner 已启动：http://${RUNNER_HOST}:${RUNNER_PORT}（模型 ${QA_MODEL}，步数上限 ${MAX_STEPS}）`);
  if (!QA_API_KEY) log("警告：未配置 QA_API_KEY，/plan 与 /execute 将无法工作。");
});

for (const signal of ["SIGINT", "SIGTERM"] as const) {
  process.on(signal, () => {
    log(`收到 ${signal}，关闭服务`);
    server.close(() => process.exit(0));
  });
}
"}

