async function agentError(response: Response, fallback: string): Promise<Error> {
  try {
    const data = await response.json()
    if (typeof data?.detail === 'string' && data.detail) return new Error(data.detail)
  } catch {
    // 非 JSON 响应（如代理层 502 的 HTML）走兜底文案。
  }
  return new Error(`${fallback}（HTTP ${response.status}）`)
}

/** 建智能体会话：上传当前场景快照与里程碑，智能体在服务端副本上迭代。 */
export async function createAgentSession(body: {
  scene: ScenePayload
  milestones: { rank: number; name: string }[]
}): Promise<AgentSessionRead> {
  const response = await postJson('/api/agent/sessions', body)
  if (!response.ok) throw await agentError(response, '无法创建智能体会话，请确认后端已启动')
  return response.json()
}

