{"file_path": "/Users/[USER]/Documents/wt-lr05-p5/frontend/src/composables/useAgentRun.ts", "content": "import { computed, ref } from 'vue'
import { storeToRefs } from 'pinia'
import { useSceneStore } from '../store/useSceneStore'
import { useValidation } from './useValidation'
import { useLayoutAssistant } from './useLayoutAssistant'
import {
  abortAgentRun,
  approveAgentRun,
  createAgentRun,
  createAgentSession,
  deleteAgentSession,
  getAgentRunDiff,
  getAgentRunEvents,
  rejectAgentRun,
} from '../api/client'
import type { AgentPlanStep, AgentRunEvent, AgentRunStatus } from '../types/api'
import type { Issue } from '../types/scene'

/**
 * 长程智能体运行：会话创建、任务提交、计划审批、SSE 进度订阅与变更收口。
 *
 * 与布置助手的分工：那个是"一问一答出一版方案"，这个是"给个目标，自己多步做完"。
 * 但**变更的呈现与应用完全复用布置助手的通道**——run 结束后拉到的 diff 直接
 * 交给 `presentProposal`，落到同一个 `pendingProposal`，由同一个 `applyProposal` /
 * `discardProposal` 收尾。预览体构建、撤销栈、土方入队、校核触发因此只有一份实现。
 *
 * 模块级单例：软锁（运行中禁止手改场景）要被 App.vue 与各编辑入口共同读取，
 * 属于跨组件的外壳状态。
 */

/** 时间线上的一步：状态、模型自述与该步内的工具调用摘要。 */
export interface RunStepEntry {
  step: number
  status: 'running' | 'done'
  text: string
  tools: { tool: string; summary: string; isError: boolean }[]
  /** 该步执行后的自动校核结论；未产生场景改动的步骤没有。 */
  validation?: { valid: boolean; issueCount: number; issues: Issue[] }
}

/** 状态机：idle → planning → awaiting_plan → running → finished/failed/aborted。 */
type RunPhase = 'idle' | AgentRunStatus

const runPhase = ref<RunPhase>('idle')
const runId = ref<string | null>(null)
const sessionId = ref<string | null>(null)
const taskInput = ref('')
const plan = ref<AgentPlanStep[]>([])
/** 用户在待批准态勾掉的步骤序号。 */
const excludedSteps = ref<number[]>([])
const steps = ref<RunStepEntry[]>([])
const runMessage = ref('')
const stopReason = ref('')
const errorText = ref('')
/** SSE 断线提示：连接掉了但 run 未收到终止事件时置位。 */
const streamLost = ref(false)
const stepsUsed = ref(0)
const maxSteps = ref(0)
/** run 结束后是否已把 diff 送进预览通道（用于「查看变更」按钮的可用性）。 */
const diffLoaded = ref(false)
const diffEmpty = ref(false)

let eventAbort: AbortController | null = null

export function useAgentRun() {
  const sceneStore = useSceneStore()
  const { milestones } = storeToRefs(sceneStore)
  const { scenePayload } = useValidation()
  const assistant = useLayoutAssistant()

  /** 运行中（含规划与待批准）：此期间手动改场景须先中止，见 §软锁。 */
  const isActive = computed(() => ['planning', 'awaiting_plan', 'running'].includes(runPhase.value))
  const isRunning = computed(() => runPhase.value === 'running')
  const awaitingPlan = computed(() => runPhase.value === 'awaiting_plan')
  const isFinished = computed(() => ['finished', 'failed', 'aborted'].includes(runPhase.value))
  const canSubmit = computed(() => !isActive.value && taskInput.value.trim().length > 0)

  /** 批准后实际会执行的步骤数（勾掉的不算）。 */
  const approvedStepCount = computed(() => plan.value.length - excludedSteps.value.length)

  function resetRunState() {
    plan.value = []
    excludedSteps.value = []
    steps.value = []
    runMessage.value = ''
    stopReason.value = ''
    errorText.value = ''
    streamLost.value = false
    stepsUsed.value = 0
    diffLoaded.value = false
    diffEmpty.value = false
  }

  function toggleStepExcluded(index: number) {
    const at = excludedSteps.value.indexOf(index)
    if (at >= 0) excludedSteps.value.splice(at, 1)
    else excludedSteps.value.push(index)
  }

  /** 取时间线上的当前步；事件里的 step 是 1 起，缺失时补一条占位而不是丢弃。 */
  function stepEntry(step: number): RunStepEntry {
    let entry = steps.value.find((item) => item.step === step)
    if (!entry) {
      entry = { step, status: 'running', text: '', tools: [] }
      steps.value.push(entry)
      steps.value.sort((left, right) => left.step - right.step)
    }
    return entry
  }

  function handleEvent(event: AgentRunEvent) {
    const payload = event.payload as Record<string, never>
    switch (event.type) {
      case 'plan_ready':
        plan.value = (payload.plan as unknown as AgentPlanStep[]) ?? []
        runPhase.value = 'awaiting_plan'
        break
      case 'step_started':
        stepEntry(Number(payload.step ?? 0)).status = 'running'
        stepsUsed.value = Math.max(stepsUsed.value, Number(payload.step ?? 0))
        break
      case 'tool_called': {
        const entry = stepEntry(Number(payload.step ?? 0))
        entry.tools.push({
          tool: String(payload.tool ?? ''),
          summary: String(payload.summary ?? ''),
          isError: Boolean(payload.is_error),
        })
        break
      }
      case 'validation_result': {
        const entry = stepEntry(Number(payload.step ?? 0))
        entry.validation = {
          valid: Boolean(payload.valid),
          issueCount: Number(payload.issue_count ?? 0),
          issues: (payload.issues as unknown as Issue[]) ?? [],
        }
        break
      }
      case 'step_finished': {
        const entry = stepEntry(Number(payload.step ?? 0))
        entry.status = 'done'
        entry.text = String(payload.text ?? '')
        stepsUsed.value = Math.max(stepsUsed.value, entry.step)
        break
      }
      case 'run_finished':
      case 'run_failed': {
        stopReason.value = String(payload.stop_reason ?? (event.type === 'run_failed' ? 'failed' : 'completed'))
        runMessage.value = String(payload.message ?? '')
        stepsUsed.value = Number(payload.steps_used ?? stepsUsed.value)
        steps.value.forEach((item) => { item.status = 'done' })
        // aborted / rejected 与正常完成分开呈现：前者场景未被应用，后者可查看变更。
        runPhase.value = event.type === 'run_failed'
          ? 'failed'
          : ['aborted', 'rejected'].includes(stopReason.value) ? 'aborted' : 'finished'
        break
      }
    }
  }

  /**
   * 订阅进度流。沿用布置助手的 fetch + getReader 消费写法（SSE 穿 vite 代理
   * 已由 /api/layout/assist/stream 证明可用）。
   *
   * 断线判定：读到流末尾但没收到终止事件即视为断线——后端在终止事件后主动关流，
   * 正常收尾一定带着终止事件，故"流没了但 run 还没结束"只可能是链路断了。
   */
  async function subscribeEvents(id: string) {
    eventAbort?.abort()
    const controller = new AbortController()
    eventAbort = controller
    let terminated = false
    try {
      const response = await getAgentRunEvents(id, controller.signal)
      if (!response) throw new Error('无法连接后端服务，请确认 FastAPI 已启动。')
      if (!response.ok || !response.body) throw new Error(`进度服务异常（HTTP ${response.status}）。`)
      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''
      for (;;) {
        const { done, value } = await reader.read()
        if (done) break
        buffer += decoder.decode(value, { stream: true })
        let boundary
        while ((boundary = buffer.indexOf('\n\n')) >= 0) {
          const rawEvent = buffer.slice(0, boundary)
          buffer = buffer.slice(boundary + 2)
          const dataLines: string[] = []
          for (const line of rawEvent.split('\n')) {
            // 以 ':' 开头的是心跳注释行，用于确认链路仍活着，无数据可解析。
            if (line.startsWith('data:')) dataLines.push(line.slice(5).trimStart())
          }
          if (!dataLines.length) continue
          const event = JSON.parse(dataLines.join('\n')) as AgentRunEvent
          handleEvent(event)
          if (event.type === 'run_finished' || event.type === 'run_failed') terminated = true
        }
      }
      if (!terminated && !controller.signal.aborted) {
        streamLost.value = true
        errorText.value = '与后端的进度连接已断开，运行可能仍在继续。可刷新页面或中止本次运行。'
      }
    } catch (error) {
      if (controller.signal.aborted) return
      streamLost.value = true
      errorText.value = (error as Error).message
    } finally {
      if (eventAbort === controller) eventAbort = null
      // run 已结束就拉取变更；断线时不拉，避免把半截结果当成最终方案。
      if (terminated) await loadDiff()
    }
  }

  /**
   * 提交任务：建会话（上传当前场景快照与里程碑）→ 建 run → 订阅进度。
   *
   * 每次任务都建新会话：智能体在服务端副本上迭代，复用旧会话会把上一轮
   * 未被应用的改动当成"现状"，与用户眼前的场景对不上。
   */
  async function submitTask() {
    const task = taskInput.value.trim()
    if (!task || isActive.value) return
    resetRunState()
    // 上一次的预览若还挂着，先静默清掉——新任务的变更会占用同一条通道。
    if (assistant.pendingProposal.value) assistant.discardProposal(true)
    runPhase.value = 'planning'
    try {
      if (sessionId.value) await deleteAgentSession(sessionId.value)
      const session = await createAgentSession({
        scene: scenePayload(),
        milestones: milestones.value.map((milestone, index) => ({ rank: index, name: milestone.name })),
      })
      sessionId.value = session.id
      const run = await createAgentRun({ session_id: session.id, task })
      runId.value = run.id
      maxSteps.value = run.max_steps
      void subscribeEvents(run.id)
    } catch (error) {
      runPhase.value = 'failed'
      errorText.value = (error as Error).message
    }
  }

  async function approvePlan() {
    if (!runId.value || !awaitingPlan.value) return
    try {
      runPhase.value = 'running'
      await approveAgentRun(runId.value, [...excludedSteps.value])
    } catch (error) {
      runPhase.value = 'failed'
      errorText.value = (error as Error).message
    }
  }

  async function rejectPlan() {
    if (!runId.value || !awaitingPlan.value) return
    try {
      await rejectAgentRun(runId.value)
    } catch (error) {
      errorText.value = (error as Error).message
    }
  }

  /**
   * 中止运行。会话副本上已落位的改动不回滚，但前端场景从未被触碰，
   * 用户不点"应用"这次运行就是零影响——故中止后不拉 diff、不进预览。
   */
  async function abortRun() {
    if (!runId.value || !isActive.value) return
    try {
      await abortAgentRun(runId.value)
    } catch (error) {
      errorText.value = (error as Error).message
    }
  }

  /** 拉取最终变更并送进布置助手的预览通道（同一条，不是复制品）。 */
  async function loadDiff() {
    if (!runId.value || diffLoaded.value) return
    // 中止/拒绝的运行不进预览：那次运行按语义就是"没发生过"。
    if (['aborted', 'rejected'].includes(stopReason.value)) return
    try {
      const diff = await getAgentRunDiff(runId.value)
      diffEmpty.value = !assistant.presentProposal(diff)
      diffLoaded.value = true
    } catch (error) {
      errorText.value = (error as Error).message
    }
  }

  /** 停止订阅并清理会话；面板关闭或场景切换时调用。 */
  async function cleanup() {
    eventAbort?.abort()
    eventAbort = null
    if (sessionId.value) {
      const id = sessionId.value
      sessionId.value = null
      await deleteAgentSession(id)
    }
  }

  return {
    taskInput, plan, excludedSteps, steps, runPhase, runMessage, stopReason, errorText,
