  function pushStep(label: string) {
    push(capture(label))
  }

  /** 拖拽类动作的起手：记下待定快照，不落栈。重复调用以最后一次为准。 */
  function beginStep(label: string) {
    pending = capture(label)
  }

  /** 拖拽类动作的收尾：把待定快照落栈。未 beginStep 或已提交过时无副作用。 */
  function commitStep() {
    if (!pending) return
    push(pending)
    pending = null
  }

