  function restore(snapshot: UndoSnapshot) {
    objects.value = clone(snapshot.objects)
    milestones.value = clone(snapshot.milestones)
    activeMilestone.value = snapshot.activeMilestone
    earthworkOperations.value.forEach((operation) => {
      const milestone = snapshot.operationMilestones[operation.id]
      if (milestone) operation.milestone = milestone
    })
    // 选中的对象可能已随撤销消失，此时退回无选中而非指向一个不存在的 id。
    selectedId.value = snapshot.objects.some((object) => object.id === snapshot.selectedId)
      ? snapshot.selectedId
      : null
    rebuildAll()
    replayEarthwork()
    checkScene()
    markDirty()
  }

  function undo() {
    const snapshot = undoStack.value[undoStack.value.length - 1]
    if (!snapshot) { note('没有可撤销的操作。'); return }
    redoStack.value = [...redoStack.value.slice(-(MAX_DEPTH - 1)), capture(snapshot.label)]
    undoStack.value = undoStack.value.slice(0, -1)
    restore(snapshot)
    note(`已撤销：${snapshot.label}。`)
  }

  function redo() {
    const snapshot = redoStack.value[redoStack.value.length - 1]
    if (!snapshot) { note('没有可重做的操作。'); return }
    undoStack.value = [...undoStack.value.slice(-(MAX_DEPTH - 1)), capture(snapshot.label)]
    redoStack.value = redoStack.value.slice(0, -1)
    restore(snapshot)
    note(`已重做：${snapshot.label}。`)
  }

  /**
   * 土方/地形侧动作发生后调用：不入栈，只在用户随后按撤销时解释原因。
   *
   * 不直接弹提示——动作当下并没有出问题，只有在用户期待"这一步能撤回"时才需要说明。
   */
  function noteOutOfScope() {
    outOfScopeSinceLastStep = true
  }

  /** 撤销入口统一走这里：先解释被跳过的土方动作，再执行栈内撤销。 */
  function requestUndo() {
    if (outOfScopeSinceLastStep) {
      outOfScopeSinceLastStep = false
      note(OUT_OF_SCOPE_NOTE)
      return
    }
    undo()
  }

  /** 场景整体重建（重新框选、存档恢复）后清栈：跨场景的快照回填的是另一副场地的内容。 */
  function clearHistory() {
    undoStack.value = []
    redoStack.value = []
    pending = null
    outOfScopeSinceLastStep = false
    undoNote.value = ''
  }

  return {
    canUndo, canRedo, undoNote,
    pushStep, beginStep, commitStep, abortStep,
    requestUndo, redo, noteOutOfScope, clearHistory,
  }
}

