import { computed } from 'vue'
import BaseButton from '../common/BaseButton.vue'
import SectionTitle from '../common/SectionTitle.vue'
import StatusChip from '../common/StatusChip.vue'
import { IconCheck, IconSend, IconWarning } from '../common/icons'
import { useAgentRun } from '../../composables/useAgentRun'
import { useLayoutAssistant } from '../../composables/useLayoutAssistant'

/**
 * 长程智能体面板：任务输入 → 计划审批 → 执行时间线 → 变更预览。
 *
 * 变更的预览与应用不在本组件内实现：run 结束后 diff 已由 useAgentRun 送进
 * 布置助手的 pendingProposal 通道，这里只呈现入口并调用同一个
 * applyProposal / discardProposal（同一条通道，不是复制品）。
 */
const {
  taskInput, plan, excludedSteps, steps, runPhase, runMessage, stopReason, errorText,
  streamLost, stepsUsed, maxSteps, diffEmpty,
  isActive, isRunning, awaitingPlan, isFinished, canSubmit, approvedStepCount,
  submitTask, approvePlan, rejectPlan, abortRun, toggleStepExcluded,
} = useAgentRun()

const { pendingProposal, proposalSummary, crossPhaseCount, applyProposal, discardProposal } = useLayoutAssistant()

/** 顶部状态条文案：一句话说清"现在在干什么、还能干什么"。 */
const phaseText = computed(() => {
  switch (runPhase.value) {
    case 'planning': return '正在制定计划…'
    case 'awaiting_plan': return '计划已就绪，请审核后开始执行'
    case 'running': return `执行中（第 ${stepsUsed.value} 步 / 上限 ${maxSteps.value}）`
    case 'finished': return stopReason.value === 'no_progress' ? '已停止：连续多步无进展' : '执行完成'
    case 'failed': return '执行失败'
    case 'aborted': return stopReason.value === 'rejected' ? '已拒绝该计划' : '已中止运行'
    default: return ''
  }
})

const phaseTone = computed(() => {
  if (runPhase.value === 'failed') return 'danger'
  if (runPhase.value === 'aborted' || stopReason.value === 'no_progress') return 'warning'
  if (runPhase.value === 'finished') return 'success'
  return 'primary'
})
</script>

